PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS roles(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, full_name TEXT NOT NULL, email TEXT, password_hash TEXT NOT NULL, role_id INTEGER NOT NULL REFERENCES roles(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS masters(id INTEGER PRIMARY KEY, master_type TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(master_type,code));
CREATE TABLE IF NOT EXISTS observations(id INTEGER PRIMARY KEY, reference_no TEXT UNIQUE NOT NULL, title TEXT NOT NULL, description TEXT, site TEXT, department TEXT, category TEXT, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', owner_id INTEGER REFERENCES users(id), due_date TEXT, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS incidents(id INTEGER PRIMARY KEY, incident_no TEXT UNIQUE NOT NULL, observation_id INTEGER REFERENCES observations(id), title TEXT NOT NULL, description TEXT, severity TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', owner_id INTEGER REFERENCES users(id), created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS capas(id INTEGER PRIMARY KEY, capa_no TEXT UNIQUE NOT NULL, observation_id INTEGER REFERENCES observations(id), incident_id INTEGER REFERENCES incidents(id), action_type TEXT NOT NULL, action TEXT NOT NULL, owner_id INTEGER REFERENCES users(id), target_date TEXT, status TEXT NOT NULL DEFAULT 'Open', effectiveness_review TEXT, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transfers(id INTEGER PRIMARY KEY, observation_id INTEGER NOT NULL REFERENCES observations(id), from_user_id INTEGER REFERENCES users(id), to_user_id INTEGER NOT NULL REFERENCES users(id), note TEXT, status TEXT NOT NULL DEFAULT 'Transferred', created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS escalations(id INTEGER PRIMARY KEY, observation_id INTEGER NOT NULL REFERENCES observations(id), level INTEGER NOT NULL DEFAULT 1, reason TEXT NOT NULL, escalated_to INTEGER REFERENCES users(id), status TEXT NOT NULL DEFAULT 'Open', created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS share_log(id INTEGER PRIMARY KEY, entity_type TEXT NOT NULL, entity_id INTEGER NOT NULL, channel TEXT NOT NULL, recipient TEXT NOT NULL, status TEXT NOT NULL, provider_message TEXT, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_trail(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, details TEXT, ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schema_migrations(version TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
